-- Migration 33: shop delivery (SRS §7, server/domain/shop.ts). Same tables as server/db/sqlite-shop.ts; money in agorot.
-- The orders checks gain the `shop` service and the `requested` status; a shop order, like a ride, is one per captain trip (DLV-24).
ALTER TABLE orders DROP CONSTRAINT orders_service_check;
ALTER TABLE orders ADD CONSTRAINT orders_service_check CHECK (service IN ('ride','parcel','freight','shop'));
ALTER TABLE orders DROP CONSTRAINT orders_status_check;
ALTER TABLE orders ADD CONSTRAINT orders_status_check CHECK (status IN ('requested','searching','assigned','at_pickup','in_transit','completed','cancelled','on_hold','returning','returned'));
ALTER TABLE orders ADD CONSTRAINT orders_requested_check CHECK (status <> 'requested' OR (service = 'shop' AND driver_id IS NULL));
ALTER TABLE ledger_accounts DROP CONSTRAINT ledger_accounts_kind_check;
ALTER TABLE ledger_accounts ADD CONSTRAINT ledger_accounts_kind_check CHECK(kind IN ('platform_revenue','driver_receivable','driver_payable','promo_expense','provider_clearing','customer_receivable','merchant_cod_payable','operating_expense'));
DROP INDEX orders_exclusive_driver;
CREATE UNIQUE INDEX orders_exclusive_driver ON orders(driver_id)
  WHERE service IN ('ride','freight','shop') AND status IN ('assigned','at_pickup','in_transit','on_hold','returning');
CREATE TABLE merchants (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, owner_user_id BIGINT NOT NULL UNIQUE REFERENCES users(id) DEFERRABLE INITIALLY DEFERRED, name TEXT NOT NULL,
  category TEXT NOT NULL CHECK (category IN ('grocery','bakery','goods')), city TEXT NOT NULL, lat DOUBLE PRECISION NOT NULL, lng DOUBLE PRECISION NOT NULL, phone TEXT,
  status TEXT NOT NULL CHECK (status IN ('pending','active','paused')), paused_new BIGINT NOT NULL DEFAULT 0 CHECK (paused_new IN (0,1)),
  min_order_agorot BIGINT NOT NULL CHECK (min_order_agorot >= 0), delivery_fee_agorot BIGINT NOT NULL CHECK (delivery_fee_agorot >= 0),
  service_fee_agorot BIGINT NOT NULL CHECK (service_fee_agorot >= 0), commission_bps BIGINT NOT NULL CHECK (commission_bps BETWEEN 0 AND 5000),
  prep_minutes BIGINT NOT NULL CHECK (prep_minutes BETWEEN 1 AND 180), licence_no TEXT NOT NULL, licence_expires_at BIGINT NOT NULL,
  created_at BIGINT NOT NULL, updated_at BIGINT NOT NULL);
CREATE TABLE merchant_hours (
  merchant_id BIGINT NOT NULL REFERENCES merchants(id) DEFERRABLE INITIALLY DEFERRED, weekday BIGINT NOT NULL CHECK (weekday BETWEEN 0 AND 6),
  open_min BIGINT NOT NULL CHECK (open_min BETWEEN 0 AND 1439), close_min BIGINT NOT NULL CHECK (close_min BETWEEN 0 AND 1440),
  PRIMARY KEY (merchant_id, weekday, open_min));
CREATE TABLE merchant_items (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, merchant_id BIGINT NOT NULL REFERENCES merchants(id) DEFERRABLE INITIALLY DEFERRED, section TEXT NOT NULL, name_ar TEXT NOT NULL, name_en TEXT NOT NULL,
  price_agorot BIGINT NOT NULL CHECK (price_agorot >= 1), by_weight BIGINT NOT NULL DEFAULT 0 CHECK (by_weight IN (0,1)),
  available BIGINT NOT NULL DEFAULT 1 CHECK (available IN (0,1)), sort BIGINT NOT NULL DEFAULT 0, updated_at BIGINT NOT NULL);
CREATE INDEX merchant_items_merchant ON merchant_items(merchant_id, section, sort);
CREATE TABLE shop_orders (
  order_id BIGINT PRIMARY KEY REFERENCES orders(id) DEFERRABLE INITIALLY DEFERRED, merchant_id BIGINT NOT NULL REFERENCES merchants(id) DEFERRABLE INITIALLY DEFERRED,
  merchant_state TEXT CHECK (merchant_state IN ('accepted','preparing','awaiting_approval','ready','handed_over')),
  accept_deadline BIGINT NOT NULL, accept_extended BIGINT NOT NULL DEFAULT 0, accepted_at BIGINT, preparing_at BIGINT, ready_at BIGINT,
  handed_over_at BIGINT, prep_minutes BIGINT, dispatch_at BIGINT, paused_at BIGINT, paused_ms BIGINT NOT NULL DEFAULT 0, no_captain_alerted_at BIGINT,
  goods_estimate_agorot BIGINT NOT NULL CHECK (goods_estimate_agorot >= 0), goods_cap_agorot BIGINT NOT NULL CHECK (goods_cap_agorot >= 0),
  goods_agorot BIGINT, delivery_fee_agorot BIGINT NOT NULL CHECK (delivery_fee_agorot >= 0), service_fee_agorot BIGINT NOT NULL CHECK (service_fee_agorot >= 0),
  agree_limit DOUBLE PRECISION NOT NULL, pickup_code TEXT NOT NULL, pickup_failures BIGINT NOT NULL DEFAULT 0, packing TEXT,
  handover_exception TEXT CHECK (handover_exception IN ('missing_item','wrong_item','damaged','package_count')), cancel_reason TEXT,
  merchant_rating BIGINT CHECK (merchant_rating BETWEEN 1 AND 5), customer_rating_by_merchant BIGINT CHECK (customer_rating_by_merchant BETWEEN 1 AND 5));
CREATE INDEX shop_orders_merchant ON shop_orders(merchant_id, merchant_state);
CREATE TABLE shop_lines (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, order_id BIGINT NOT NULL REFERENCES orders(id) DEFERRABLE INITIALLY DEFERRED, item_id BIGINT REFERENCES merchant_items(id) DEFERRABLE INITIALLY DEFERRED,
  name_ar TEXT NOT NULL, name_en TEXT NOT NULL, policy TEXT NOT NULL CHECK (policy IN ('remove','ask_first','similar')),
  by_weight BIGINT NOT NULL CHECK (by_weight IN (0,1)), qty_milli BIGINT NOT NULL CHECK (qty_milli > 0),
  unit_agorot BIGINT NOT NULL CHECK (unit_agorot >= 0), estimate_agorot BIGINT NOT NULL CHECK (estimate_agorot >= 0),
  final_agorot BIGINT CHECK (final_agorot >= 0), removed BIGINT NOT NULL DEFAULT 0 CHECK (removed IN (0,1)), substitute_for BIGINT);
CREATE INDEX shop_lines_order ON shop_lines(order_id);
CREATE TABLE shop_snapshots (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, order_id BIGINT NOT NULL REFERENCES orders(id) DEFERRABLE INITIALLY DEFERRED,
  reason TEXT NOT NULL CHECK (reason IN ('placement','edit','consent','merchant_change','ready')),
  goods_agorot BIGINT NOT NULL, body TEXT NOT NULL, created_at BIGINT NOT NULL);
CREATE INDEX shop_snapshots_order ON shop_snapshots(order_id, id);
CREATE TABLE shop_changes (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, order_id BIGINT NOT NULL REFERENCES orders(id) DEFERRABLE INITIALLY DEFERRED, line_id BIGINT NOT NULL,
  kind TEXT NOT NULL CHECK (kind IN ('weight','substitution')), payload TEXT NOT NULL,
  status TEXT NOT NULL CHECK (status IN ('pending','approved','declined','expired')), expires_at BIGINT NOT NULL,
  extended BIGINT NOT NULL DEFAULT 0, created_at BIGINT NOT NULL, decided_at BIGINT);
CREATE UNIQUE INDEX shop_changes_pending ON shop_changes(order_id) WHERE status = 'pending';
CREATE TABLE shop_handover_checks (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, order_id BIGINT NOT NULL REFERENCES orders(id) DEFERRABLE INITIALLY DEFERRED, actor_id BIGINT NOT NULL REFERENCES users(id) DEFERRABLE INITIALLY DEFERRED,
  result TEXT NOT NULL CHECK (result IN ('ok','exception')),
  exception TEXT CHECK (exception IN ('missing_item','wrong_item','damaged','package_count')), note TEXT NOT NULL DEFAULT '', created_at BIGINT NOT NULL);
CREATE TABLE shop_seals (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, order_id BIGINT NOT NULL REFERENCES orders(id) DEFERRABLE INITIALLY DEFERRED, package_no BIGINT NOT NULL,
  intact BIGINT NOT NULL CHECK (intact IN (0,1)), attempt TEXT NOT NULL CHECK (attempt IN ('deliver','fail')),
  actor_id BIGINT NOT NULL REFERENCES users(id) DEFERRABLE INITIALLY DEFERRED, created_at BIGINT NOT NULL);
CREATE TABLE shop_faults (
  order_id BIGINT PRIMARY KEY REFERENCES orders(id) DEFERRABLE INITIALLY DEFERRED, result TEXT NOT NULL CHECK (result IN ('merchant','wind','none')),
  actor_id BIGINT NOT NULL REFERENCES users(id) DEFERRABLE INITIALLY DEFERRED, note TEXT NOT NULL, created_at BIGINT NOT NULL);
CREATE TABLE shop_ledger (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, book TEXT NOT NULL CHECK (book IN ('merchant','captain','wind')),
  merchant_id BIGINT REFERENCES merchants(id) DEFERRABLE INITIALLY DEFERRED, driver_id BIGINT REFERENCES users(id) DEFERRABLE INITIALLY DEFERRED, order_id BIGINT REFERENCES orders(id) DEFERRABLE INITIALLY DEFERRED,
  kind TEXT NOT NULL, amount_agorot BIGINT NOT NULL CHECK (amount_agorot <> 0), note TEXT NOT NULL, reference TEXT,
  actor_id BIGINT NOT NULL REFERENCES users(id) DEFERRABLE INITIALLY DEFERRED, business_ref TEXT NOT NULL UNIQUE, created_at BIGINT NOT NULL);
CREATE INDEX shop_ledger_merchant ON shop_ledger(book, merchant_id, id);
CREATE INDEX shop_ledger_driver ON shop_ledger(book, driver_id);

CREATE FUNCTION shop_append_only() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN RAISE EXCEPTION '% is append-only', TG_TABLE_NAME USING ERRCODE='23514'; END $$;
CREATE TRIGGER shop_snapshots_append_only BEFORE UPDATE OR DELETE ON shop_snapshots FOR EACH ROW EXECUTE FUNCTION shop_append_only();
CREATE TRIGGER shop_checks_append_only BEFORE UPDATE OR DELETE ON shop_handover_checks FOR EACH ROW EXECUTE FUNCTION shop_append_only();
CREATE TRIGGER shop_seals_append_only BEFORE UPDATE OR DELETE ON shop_seals FOR EACH ROW EXECUTE FUNCTION shop_append_only();
CREATE TRIGGER shop_faults_append_only BEFORE UPDATE OR DELETE ON shop_faults FOR EACH ROW EXECUTE FUNCTION shop_append_only();
CREATE TRIGGER shop_ledger_append_only BEFORE UPDATE OR DELETE ON shop_ledger FOR EACH ROW EXECUTE FUNCTION shop_append_only();
CREATE TRIGGER shop_ledger_no_truncate BEFORE TRUNCATE ON shop_ledger FOR EACH STATEMENT EXECUTE FUNCTION shop_append_only();
